INSERT INTO `faqs` (`id`, `question`, `answer`, `status`, `date`, `created_at`, `updated_at`) VALUES
(1, 'What residence configurations are available?', 'The estate currently showcases 1 BHK villament, with additional 2 BHK villament and 3 BHK duplex options presented through the residences section.', '1', '06-08-2026 06:11:42', NULL, '2026-09-25 02:37 PM'),
(2, 'Can I schedule a private site visit?', 'Yes. You can request a private guided visit through the contact page, and the estate team will coordinate a convenient time with you.', '1', '06-08-2026 06:11:42', NULL, NULL),
(3, 'Which amenities are included for residents?', 'Residents are planned to enjoy landscaped gardens, wellness areas, private decks, security support, concierge-style assistance, and curated lifestyle spaces.', '1', '06-08-2026 06:11:42', NULL, NULL),
(4, 'Is The Ulhas Vilas compliant and title verified?', 'Project documentation, approvals, and title-related details can be reviewed with our sales and legal coordination team during your private consultation.', '1', '06-08-2026 06:11:42', NULL, NULL),
(11, 'What architectural customization options are available?', 'Buyers can discuss layout preferences, finish palettes, outdoor decks, premium fittings, and selected interior upgrades with the estate team.', '1', NULL, NULL, NULL);
